function markDone(items, id) {
  return items.map(function (item) {
    return item.id === id ? Object.assign({}, item, { done: true }) : item;
  });
}

var list = [{ id: 1, done: false }, { id: 2, done: false }];
console.log(JSON.stringify(markDone(list, 2)));
